const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Dallasport, Washington coordinates
  const point = ee.Geometry.Point([-121.1784, 45.6184]);
  const startDate = '2022-07-01';
  const endDate = '2022-07-31';

  // 2. Data Acquisition & Check
  // ERA5-Land hourly data for 2m air temperature
  const collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(point)
    .select('temperature_2m');

  const count = collection.size().getInfo();
  console.log(`Images found: ${count}`);

  if (count === 0) {
    console.log("No data available for July 2022.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get maximum temperature
  const maxTemp = collection.max();

  // 4. Calculate maximum temperature at the point
  const tempStats = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: point,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const maxTempK = tempStats.temperature_2m;

  // 5. Validation & Final Answer
  if (maxTempK === null || maxTempK === undefined) {
    console.log("Temperature calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  const maxTempF = (maxTempK - 273.15) * 9/5 + 32;

  console.log(`Max temperature in July 2022: ${maxTempF.toFixed(2)}°F (${maxTempK.toFixed(2)}K)`);
  console.log(`Threshold: 95°F (308.15K)`);

  if (maxTempF >= 95) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
